/**
 * Beck et al. (2023) Köppen–Geiger climate classification, 1901–1930, 0.5°.
 * Source DOI: 10.6084/m9.figshare.c.6395666.v1 · License: CC0.
 * Generated by scratch/generate_koppen_grid.py; do not hand-edit the payload.
 */

export const KOPPEN_GRID_WIDTH = 720;
export const KOPPEN_GRID_HEIGHT = 360;
export const KOPPEN_GRID_STEP_DEG = 0.5;

const KOPPEN_RLE_BASE64 = '';

let decodedGrid: Uint8Array | null = null;

function decodeGrid(): Uint8Array {
    if (decodedGrid) return decodedGrid;
    const bytes = Uint8Array.from(atob(KOPPEN_RLE_BASE64), (char) => char.charCodeAt(0));
    const grid = new Uint8Array(KOPPEN_GRID_WIDTH * KOPPEN_GRID_HEIGHT);
    let source = 0;
    let target = 0;
    while (source + 2 < bytes.length) {
        const value = bytes[source];
        const count = bytes[source + 1] | (bytes[source + 2] << 8);
        grid.fill(value, target, target + count);
        source += 3;
        target += count;
    }
    if (target !== grid.length) throw new Error(`Köppen grid length mismatch: ${target}/${grid.length}`);
    decodedGrid = grid;
    return grid;
}

function classAtCell(x: number, y: number): number {
    if (x < 0 || x >= KOPPEN_GRID_WIDTH || y < 0 || y >= KOPPEN_GRID_HEIGHT) return 0;
    return decodeGrid()[y * KOPPEN_GRID_WIDTH + x];
}

/** 返回 1–30 的 Köppen 类别；海岸空格会在相邻 1°内寻找最近陆地格。 */
export function koppenClassIdAt(lat: number, lng: number): number | null {
    const x = Math.max(0, Math.min(KOPPEN_GRID_WIDTH - 1, Math.floor((lng + 180) / KOPPEN_GRID_STEP_DEG)));
    const y = Math.max(0, Math.min(KOPPEN_GRID_HEIGHT - 1, Math.floor((90 - lat) / KOPPEN_GRID_STEP_DEG)));
    const direct = classAtCell(x, y);
    if (direct > 0) return direct;
    for (let radius = 1; radius <= 2; radius++) {
        let best: { value: number; distance2: number } | null = null;
        for (let dy = -radius; dy <= radius; dy++) {
            for (let dx = -radius; dx <= radius; dx++) {
                if (Math.max(Math.abs(dx), Math.abs(dy)) !== radius) continue;
                const value = classAtCell(x + dx, y + dy);
                if (value <= 0) continue;
                const distance2 = dx * dx + dy * dy;
                if (!best || distance2 < best.distance2) best = { value, distance2 };
            }
        }
        if (best) return best.value;
    }
    return null;
}
